-- ============================================
-- LUMA — Thème 2 : 3e scénario COURT x4 — Un compliment maladroit à rattraper
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "You just said: ''Wow, you look way better in person than in your photos!''", "text_fr": "Vous venez de dire : ''Waouh, tu es bien mieux en vrai que sur tes photos !''", "choices": [{"text": "(Realize how that sounded and try to fix it immediately.)", "text_fr": "(Réalise comment ça a sonné et essaie de rattraper ça immédiatement.)", "next": "n2"}, {"text": "(Laugh it off and hope they didn''t notice.)", "text_fr": "(Ris pour détendre l''atmosphère et espère qu''ils n''ont rien remarqué.)", "next": "n2b"}]}, "n2": {"speaker": "alex", "text": "(Laughs awkwardly) Uh... thanks? I think?", "text_fr": "(Rit maladroitement) Euh... merci ? Je crois ?", "choices": [{"text": "Sorry, that came out wrong! I meant your photos don''t do you justice.", "text_fr": "Désolé, c''est mal sorti ! Je voulais dire que tes photos ne te rendent pas justice.", "next": "n3"}, {"text": "Oh no, I didn''t mean it like that — I just meant you have a great smile in person.", "text_fr": "Oh non, je ne voulais pas dire ça comme ça — je voulais dire que tu as un beau sourire en vrai.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "(Raises an eyebrow slightly, a bit confused.)", "text_fr": "(Hausse légèrement un sourcil, un peu confus.)", "choices": [{"text": "Actually wait, let me rephrase that — it came out weird.", "text_fr": "En fait attends, laisse-moi reformuler — c''est sorti bizarrement.", "next": "n3"}, {"text": "(Change the subject quickly.) So, have you been here before?", "text_fr": "(Change de sujet rapidement.) Alors, t''es déjà venu ici ?", "next": "n3b"}]}, "n3": {"speaker": "alex", "text": "Oh, okay! That''s actually really sweet, thank you.", "text_fr": "Oh, d''accord ! C''est en fait très gentil, merci.", "choices": [{"text": "Phew, I''m glad that landed better this time.", "text_fr": "Ouf, je suis content que ça passe mieux cette fois.", "next": "n4"}]}, "n3b": {"speaker": "alex", "text": "A couple times actually, the coffee here is great.", "text_fr": "Quelques fois en fait, le café ici est excellent.", "choices": [{"text": "Actually, before we move on — I want to say something I said sounded weird.", "text_fr": "En fait, avant de continuer — je veux dire que ce que j''ai dit a sonné bizarre.", "next": "n4b"}, {"text": "(Just let it go and continue the conversation naturally.)", "text_fr": "(Laisse tomber et continue la conversation naturellement.)", "next": "n4c"}]}, "n4": {"speaker": "alex", "text": "Don''t worry about it, it''s kind of endearing when people get flustered.", "text_fr": "T''inquiète pas, c''est plutôt attachant quand les gens sont troublés.", "choices": [{"text": "Well, you definitely have that effect on me.", "text_fr": "Eh bien, tu as clairement cet effet sur moi.", "next": "end_recovered"}]}, "n4b": {"speaker": "alex", "text": "Oh, don''t worry, I actually thought it was kind of funny.", "text_fr": "Oh, t''inquiète, j''ai en fait trouvé ça plutôt drôle.", "choices": [{"text": "Ha, well, at least it broke the ice, right?", "text_fr": "Ha, bon, au moins ça a brisé la glace, non ?", "next": "end_recovered"}]}, "n4c": {"speaker": "alex", "text": "(The conversation flows naturally, the moment passes.)", "text_fr": "(La conversation coule naturellement, le moment passe.)", "choices": [{"text": "(Feel relieved that it wasn''t a big deal after all.)", "text_fr": "(Ressens du soulagement que ça n''ait pas été si grave finalement.)", "next": "end_ignored"}]}, "end_recovered": {"speaker": "alex", "text": "Honestly, I appreciate that you tried to fix it. That says a lot.", "text_fr": "Honnêtement, j''apprécie que tu aies essayé de rattraper ça. Ça en dit long.", "end": true, "ending_label": "Maladresse transformée en moment attachant 😅💕"}, "end_ignored": {"speaker": "alex", "text": "(The date continues smoothly, the awkward moment forgotten.)", "text_fr": "(Le rendez-vous continue en douceur, le moment gênant oublié.)", "end": true, "ending_label": "Moment gênant vite oublié 😌"}}}'::jsonb, is_playable = true
where title = 'Un compliment maladroit à rattraper'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
